<?php require_once 'includes/config.php'; require_teacher();$tid=current_teacher_id();$q=$dbh->prepare('SELECT rs.*,s.StudentName,s.RollId,c.ClassName,c.Section FROM result_submissions rs JOIN tblstudents s ON s.StudentId=rs.student_id JOIN tblclasses c ON c.id=rs.class_id WHERE rs.teacher_id=:t ORDER BY rs.updated_at DESC,rs.created_at DESC');$q->execute([':t'=>$tid]);$rows=$q->fetchAll();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Submissions | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body><nav class="navbar navbar-default srms-mobile-nav"><div class="container-fluid"><a class="navbar-brand" href="teacher-dashboard.php"><?php echo e(srms_school_name());?></a><p class="navbar-text pull-right"><img src="profile-photo.php?type=teacher&id=<?php echo (int)($_SESSION['teacher_id']??0);?>" alt="Profile photo" width="28" height="28" style="border-radius:50%;object-fit:cover" onerror="this.style.display='none'"> <?php echo e($_SESSION['teacher_name']??'Teacher');?> · <a href="teacher-logout.php">Sign out</a></p></div></nav><div class="container-fluid srms-page"><div class="srms-toolbar"><a class="btn btn-default" href="teacher-dashboard.php">← Dashboard</a><a class="btn btn-danger pull-right" href="teacher-logout.php">Logout</a></div><h2>My Result Submissions</h2><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Student</th><th>Class</th><th>Academic Year</th><th>Exam</th><th>Status</th><th>Submitted</th><th>Reason</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php echo e($r['StudentName'].' ('.$r['RollId'].')');?></td><td><?php echo e($r['ClassName'].' '.$r['Section']);?></td><td><?php echo e($r['academic_year']);?></td><td><?php echo e($r['exam_type']);?></td><td><span class="label label-<?php echo $r['submission_status']==='approved'?'success':($r['submission_status']==='rework'?'danger':'warning');?>"><?php echo e(result_status_label($r['submission_status']));?></span></td><td><?php echo e($r['submitted_at']??'—');?></td><td><?php echo e($r['rejection_reason']??'');?></td></tr><?php endforeach;?></tbody></table></div></div></body></html>
